"""Writes tests/diff/lib/dx.bend: the static helpers plus one eager wrapper per available verb
and the shims of facade defs a generated case needs that frame.bend lacks (lit_null, abs, sqrt)."""
import emit
import model as M

STATIC = '''# tests/diff/lib/dx.bend -- shared helpers of the generated differential cases (bench/diff).
# GENERATED by `python bench/diff/gen.py --lib`: the static part below, one `e_<verb>` wrapper
# per facade verb (an Fail passes through, like tests/regress/lib/rx.bend) and shims for the
# few expression builders frame.bend does not export yet. Do not edit by hand.
# Not a test itself: its main prints nothing.
import Base
import ./../../../frame.bend as DF
import ./../../../src/dtype.bend as D
import ./../../../src/err.bend as E
import ./../../../src/column.bend as C
import ./../../../src/schema.bend as S
import ./../../../src/expr.bend as X
import ./../../../src/sort.bend as O
import ./../../../src/plan.bend as P

# ---- dtypes ---------------------------------------------------------------------------

def t_bool() -> D.DType:
  D.TBool{}

def t_u32() -> D.DType:
  D.TU32{}

def t_i32() -> D.DType:
  D.TI32{}

def t_f32() -> D.DType:
  D.TF32{}

def t_str() -> D.DType:
  D.TStr{}

# ---- frames ---------------------------------------------------------------------------

def mk.k(name: String, r: E.ResT(C.Column)) -> C.Named:
  match r:
    case Fail{e}:
      C.Named{E.Err.show(e), C.CU32{0, 0n, C.AllValid{}, [0 : U32*1n]}}
    case Done{c}:
      C.Named{name, c}

def mk(name: String, xs: List<&2, D.Scalar>, +t: D.DType) -> C.Named:
  mk.k(name, C.Column.from_scalars(xs, t))

def cbool(name: String, xs: List<&2, D.Scalar>) -> C.Named:
  mk(name, xs, D.TBool{})

def cu32(name: String, xs: List<&2, D.Scalar>) -> C.Named:
  mk(name, xs, D.TU32{})

def ci32(name: String, xs: List<&2, D.Scalar>) -> C.Named:
  mk(name, xs, D.TI32{})

def cf32(name: String, xs: List<&2, D.Scalar>) -> C.Named:
  mk(name, xs, D.TF32{})

def cstr(name: String, xs: List<&2, D.Scalar>) -> C.Named:
  mk(name, xs, D.TStr{})

# a str column in the Dictionary storage (M4; `run.py --dict` emits it for every str column)
def mkd.k(nc: C.Named) -> C.Named:
  match nc:
    case C.Named{n, c}:
      C.Named{n, C.Column.encode(c)}

def cstrd(name: String, xs: List<&2, D.Scalar>) -> C.Named:
  mkd.k(mk(name, xs, D.TStr{}))

def frame(cols: List<&1, C.Named>) -> E.ResT(C.Frame):
  DF.from_columns(cols)

# ---- scalars --------------------------------------------------------------------------

def n() -> D.Scalar:
  D.SNull{}

def b(x: Bool) -> D.Scalar:
  D.SBool{x}

def u(x: U32) -> D.Scalar:
  D.SU32{x}

def i(x: U32) -> D.Scalar:
  D.SI32{D.I32{x}}

def ineg(x: U32) -> D.Scalar:
  D.SI32{D.I32.neg(D.I32{x})}

def f(x: F32) -> D.Scalar:
  D.SF32{x}

def s(x: String) -> D.Scalar:
  D.SStr{x}

def ch(c: U32) -> String:
  SCon{Chr{c}, SNil{}}

def nan() -> F32:
  F32.div(0.0, 0.0)

def inf() -> F32:
  F32.div(1.0, 0.0)

def ninf() -> F32:
  F32.neg(F32.div(1.0, 0.0))

def nzero() -> F32:
  F32.neg(0.0)

# ---- lazy sources ---------------------------------------------------------------------

def env.k(r: P.Env & P.Plan) -> P.Env:
  (env, p) = r
  env

def plan.k(r: P.Env & P.Plan) -> P.Plan:
  (env, p) = r
  p

def env1(+name: String, r: E.ResT(C.Frame)) -> P.Env:
  match r:
    case Fail{e}:
      DF.empty_env()
    case Done{fr}:
      env.k(DF.source(name, fr))

def env_add(env: P.Env, +name: String, r: E.ResT(C.Frame)) -> P.Env:
  match r:
    case Fail{e}:
      env
    case Done{fr}:
      env.k(P.Env.add(env, name, fr))

def env2(+n1: String, r1: E.ResT(C.Frame), +n2: String, r2: E.ResT(C.Frame)) -> P.Env:
  env_add(env1(n1, r1), n2, r2)

# the Source plan of a frame (its schema); the frame itself is dropped
def src(+name: String, r: E.ResT(C.Frame)) -> P.Plan:
  match r:
    case Fail{e}:
      P.Source{name, Nil{}}
    case Done{fr}:
      plan.k(DF.source(name, fr))

# ---- printing -------------------------------------------------------------------------

def show(+tag: String, how: String, r: E.ResT(C.Frame)) -> String:
  "-- " ++ tag ++ " " ++ how ++ "\\n" ++ DF.dump(r)

# eager, raw-lazy (DF.collect_raw), default-optimised (DF.collect) and fully optimised
# (DF.collect_full) dumps of one case; each lazy run gets its own env (collect consumes it)
def four(+tag: String, eager: E.ResT(C.Frame), +p: P.Plan, e1: P.Env, e2: P.Env, e3: P.Env) -> IO(Unit):
  do IO<Unit>:
    r1 : E.ResT(C.Frame) <- DF.collect_raw(p, e1)
    r2 : E.ResT(C.Frame) <- DF.collect(p, e2)
    r3 : E.ResT(C.Frame) <- DF.collect_full(p, e3)
    IO.print(show(tag, "eager", eager))
    IO.print(show(tag, "raw", r1))
    IO.print(show(tag, "opt", r2))
    IO.print(show(tag, "full", r3))

# G1 (v0.2 T5.3): the four runs above, then the chunked engine (src/cexec.bend) on the plan as written
# at grains 2^2 and 2^4 (DF.collect_raw_with: compared with raw) and collect at the default grain 2^14
# (DF.collect_with: compared with opt); run.py --chunked emits this step instead of `four`
def seven(+tag: String, eager: E.ResT(C.Frame), +p: P.Plan, e1: P.Env, e2: P.Env, e3: P.Env, e4: P.Env, e5: P.Env, e6: P.Env) -> IO(Unit):
  do IO<Unit>:
    r1 : E.ResT(C.Frame) <- DF.collect_raw(p, e1)
    r2 : E.ResT(C.Frame) <- DF.collect(p, e2)
    r3 : E.ResT(C.Frame) <- DF.collect_full(p, e3)
    r4 : E.ResT(C.Frame) <- DF.collect_raw_with(DF.engine_chunked_at(2n), p, e4)
    r5 : E.ResT(C.Frame) <- DF.collect_raw_with(DF.engine_chunked_at(4n), p, e5)
    r6 : E.ResT(C.Frame) <- DF.collect_with(DF.engine_chunked(), p, e6)
    IO.print(show(tag, "eager", eager))
    IO.print(show(tag, "raw", r1))
    IO.print(show(tag, "opt", r2))
    IO.print(show(tag, "full", r3))
    IO.print(show(tag, "c2", r4))
    IO.print(show(tag, "c4", r5))
    IO.print(show(tag, "c14", r6))
'''

LIT_NULL = '''def lit_null(t: D.DType) -> X.Expr:
  X.Cast{X.Lit{D.SNull{}}, t}
'''


def wrapper(verb: str) -> str:
    decls = emit.VERB_DECLS[verb]
    spec = M.VERBS[verb]
    ps = "".join(f", {n}: {t}" for n, t in decls)
    args = ", ".join(n for n, _ in decls)
    if spec.nin == 1:
        return f'''def e_{verb}(r: E.ResT(C.Frame){ps}) -> E.ResT(C.Frame):
  match r:
    case Fail{{e}}:
      Fail{{e}}
    case Done{{fr}}:
      DF.{verb}(fr{", " + args if args else ""})
'''
    if spec.nin == 2:
        return f'''def e_{verb}.k(l: C.Frame, r: E.ResT(C.Frame){ps}) -> E.ResT(C.Frame):
  match r:
    case Fail{{e}}:
      Fail{{e}}
    case Done{{fr}}:
      DF.{verb}(l, fr{", " + args if args else ""})

def e_{verb}(l: E.ResT(C.Frame), r: E.ResT(C.Frame){ps}) -> E.ResT(C.Frame):
  match l:
    case Fail{{e}}:
      Fail{{e}}
    case Done{{fl}}:
      e_{verb}.k(fl, r{", " + args if args else ""})
'''
    # variadic (concat_vertical): input by input, as the lazy chain of binary Concat nodes types it
    # (DESIGN.md 14 "M3 table verbs"): input i's error, then its schema against input 0's
    # (InvalidOperation "concat_vertical: input <i> schema [..] differs from input 0's [..]"), then
    # input i + 1; when every input is a frame of input 0's schema, DF.concat_vertical (row cap)
    return '''def e_concat_vertical.chk(same: Bool, f: C.Frame, +i: U32, s: List<&2, S.Field>, s0: List<&2, S.Field>, acc: List<&1, C.Frame>) -> E.ResT(List<&1, C.Frame>):
  match same:
    case True{}:
      Done{f <> acc}
    case False{}:
      Fail{E.InvalidOperation{"concat_vertical: input " ++ U32.show(i) ++ " schema [" ++ S.Schema.show(s) ++ "] differs from input 0's [" ++ S.Schema.show(s0) ++ "]"}}

def e_concat_vertical.sch(r: C.Frame & List<&2, S.Field>, +i: U32, +s0: List<&2, S.Field>, acc: List<&1, C.Frame>) -> E.ResT(List<&1, C.Frame>):
  (f, +s) = r
  e_concat_vertical.chk(S.Schema.eq(s, s0), f, i, s, s0, acc)

def e_concat_vertical.put(h: E.ResT(C.Frame), +i: U32, +s0: List<&2, S.Field>, acc: List<&1, C.Frame>) -> E.ResT(List<&1, C.Frame>):
  match h:
    case Fail{e}:
      Fail{e}
    case Done{f}:
      e_concat_vertical.sch(S.Frame.schema(f), i, s0, acc)

def e_concat_vertical.step(st: E.ResT(List<&1, C.Frame>), h: E.ResT(C.Frame), +i: U32, +s0: List<&2, S.Field>) -> E.ResT(List<&1, C.Frame>):
  match st:
    case Fail{e}:
      Fail{e}
    case Done{acc}:
      e_concat_vertical.put(h, i, s0, acc)

def e_concat_vertical.go(rs: List<&1, E.ResT(C.Frame)>, +i: U32, +s0: List<&2, S.Field>, st: E.ResT(List<&1, C.Frame>)) -> E.ResT(List<&1, C.Frame>):
  match rs:
    case Nil{}:
      st
    case h <> t:
      e_concat_vertical.go(t, U32.inc(i), s0, e_concat_vertical.step(st, h, i, s0))

def e_concat_vertical.fin(r: E.ResT(List<&1, C.Frame>)) -> E.ResT(C.Frame):
  match r:
    case Fail{e}:
      Fail{e}
    case Done{acc}:
      DF.concat_vertical(List.reverse(&1, C.Frame, acc))

def e_concat_vertical.first(r: C.Frame & List<&2, S.Field>, t: List<&1, E.ResT(C.Frame)>) -> E.ResT(C.Frame):
  (f, +s0) = r
  e_concat_vertical.fin(e_concat_vertical.go(t, 1, s0, Done{f <> Nil{}}))

def e_concat_vertical.k(h: E.ResT(C.Frame), t: List<&1, E.ResT(C.Frame)>) -> E.ResT(C.Frame):
  match h:
    case Fail{e}:
      Fail{e}
    case Done{f}:
      e_concat_vertical.first(S.Frame.schema(f), t)

def e_concat_vertical(rs: List<&1, E.ResT(C.Frame)>) -> E.ResT(C.Frame):
  match rs:
    case Nil{}:
      DF.concat_vertical(Nil{})
    case h <> t:
      e_concat_vertical.k(h, t)
'''


def build(all_=False) -> str:
    fac = M.facade_defs()
    parts = [STATIC, "# ---- shims (facade defs missing from frame.bend) ----\n"]
    if "lit_null" not in fac:
        parts.append(LIT_NULL)
    for n, spec in M.EXPRS.items():
        if spec.shim and n not in fac:
            parts.append(spec.shim + "\n")
    parts.append("# ---- eager verb wrappers ----\n")
    for v in M.VERBS:
        if M.verb_available(v, all_):
            parts.append(wrapper(v))
    parts.append("def main() -> IO(Unit):\n  IO.pure(Unit, Unit{})\n")
    return "\n".join(parts)
